#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.EventSystems;
using HeartOfTheRain.App.Home;using HeartOfTheRain.App.FirstStart;using HeartOfTheRain.App.PreLevel;
using HeartOfTheRain.App.Profile;using HeartOfTheRain.App.AccountDesign;using HeartOfTheRain.M47;
namespace HeartOfTheRain.Verification {
 [InitializeOnLoad] public static class IndependentPageCorrectionsReview {
  const string Key="HOTR.IndependentPageCorrections";static double started;static int phase;static HomeLevelFlow flow;static HomePage home;static PreLevelModal modal;
  [Serializable] sealed class Report {public string status="RUNNING",utc,error;public int cycles;public bool staleRecoveryIgnored,rainCupFocus,accountRetryFocus,resourcesBound;public string scope="Native Editor isolated loading-art close/reopen lifetime, stale recovery guard, page focus and resource bindings; no owner save or device mutations.";}
  sealed class OfflineAccount:IAccountService {public AccountStatus Read()=>new AccountStatus{localSaved=true,online=false};public void Link(string p,Action<AccountLinkResult> done)=>done(AccountLinkResult.Failed);}
  static Report report;static string Output=>Path.GetFullPath(System.Environment.GetEnvironmentVariable("HOTR_REVIEW93_OUT")??"../Verification/Evidence/IndependentReview66");
  static IndependentPageCorrectionsReview(){if(SessionState.GetBool(Key,false)){started=EditorApplication.timeSinceStartup;report=new Report{utc=DateTime.UtcNow.ToString("o")};EditorApplication.update+=Tick;}}
  public static void Run(){SessionState.SetBool(Key,true);EditorSceneManager.OpenScene("Assets/HeartOfTheRain/App/FirstStart/Scenes/M65_First_Start.unity");UnityEngine.Object.FindFirstObjectByType<FirstStartPage>().reviewAlways=true;EditorApplication.isPlaying=true;}
  static void Tick(){try{
   if(EditorApplication.timeSinceStartup-started>60)throw new TimeoutException("Art lifetime phase "+phase);if(!EditorApplication.isPlaying||EditorApplication.isCompiling||EditorApplication.isUpdating)return;
   if(phase==0){home=UnityEngine.Object.FindFirstObjectByType<HomePage>();flow=UnityEngine.Object.FindFirstObjectByType<HomeLevelFlow>();if(!home||!flow||!flow.Loading)return;var first=home.GetComponent<FirstStartPage>();if(!first||!first.Initialized)return;if(first.IsVisible){first.Request("skip");first.Request("skip");}modal=home.GetComponent<PreLevelModal>();if(flow.Loading.art)throw new Exception("Loading art resident before pre-level");flow.Open(1);phase=1;return;}
   if(phase==10){var game=UnityEngine.Object.FindFirstObjectByType<GameplayScreen>();if(!game||!game.InitializationComplete||game.ReviewInputBlocked)return;var host=home.GetComponent<PlayerProfileHost>();string saved=JsonUtility.ToJson(host.Service.Read());typeof(HomeLevelFlow).GetMethod("ReleaseStartedLaunch",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(flow,new object[]{new PreLevelTicket(),int.MinValue});if(!game||game!=UnityEngine.Object.FindFirstObjectByType<GameplayScreen>()||JsonUtility.ToJson(host.Service.Read())!=saved)throw new Exception("Stale committed-start recovery affected the live attempt");report.staleRecoveryIgnored=true;flow.ReturnHomeForReview();host.Service.Change(p=>{p.completed=10;p.currentLevel=11;return true;});host.Refresh();var cup=home.GetComponent<RainCupPage>();cup.Show();cup.Request("join");if(!EventSystem.current||EventSystem.current.currentSelectedGameObject?.name!="close")throw new Exception("Rain Cup join lost focus");report.rainCupFocus=true;cup.Hide();var account=home.GetComponent<AccountModal>();if(!account)account=home.gameObject.AddComponent<AccountModal>();account.Configure(home,AccountDesignAssets.Load());account.Show(new OfflineAccount());account.Request("retry");if(EventSystem.current.currentSelectedGameObject?.name!="Account close")throw new Exception("Account retry lost focus");report.accountRetryFocus=true;account.Hide();Finish(0);return;}
   if(!flow.Loading.art)return;
   if(flow.Loading.art.sprites.Any(s=>!s||!s.texture))throw new Exception("Missing sprite/texture after close/reopen at cycle "+report.cycles);
   report.cycles++;if(report.cycles==4){foreach(var path in new[]{"HOTR_Account/Config","HOTR_DailyGift/Design","HOTR_GameplayLoading/Design","HOTR_HomeLives/Design","HOTR_RainCup/Design","HOTR_UIClarity/Config","HOTR_Wellworks/Design"}){var asset=Resources.Load(path);if(!asset)throw new Exception("Required resource missing: "+path);foreach(var f in asset.GetType().GetFields(BindingFlags.Instance|BindingFlags.Public))if(typeof(UnityEngine.Object).IsAssignableFrom(f.FieldType)&&!(UnityEngine.Object)f.GetValue(asset))throw new Exception("Null resource reference "+path+"/"+f.Name);}report.resourcesBound=true;modal.Requested("play");phase=10;return;}
   modal.Requested("close");if(flow.Loading.art)throw new Exception("Art binding retained on close");flow.Open(1);
   if(report.cycles==2){modal.Requested("close");flow.Open(1);}phase++;
  }catch(Exception e){report.error=e.ToString();Finish(1);}}
  static void Finish(int code){report.status=code==0?"PASS_NATIVE_LOADING_ART_LIFETIME":"FAIL_NATIVE_LOADING_ART_LIFETIME";Directory.CreateDirectory(Output);File.WriteAllText(Path.Combine(Output,"Loading_Art_Lifetime.json"),JsonUtility.ToJson(report,true));SessionState.EraseBool(Key);EditorApplication.update-=Tick;EditorApplication.Exit(code);}
 }
}
#endif
